```python
totals = {}
counts = {}

for record in records:
    city = record["city"]
    totals[city] = totals.get(city, 0) + record["score"]
    counts[city] = counts.get(city, 0) + 1

averages = {}
for city in totals:
    averages[city] = totals[city] / counts[city]

for city in sorted(averages):
    print(city, averages[city])
